    schema: "yaml-1.1",
    customTags: yaml_write_tags,
    ...YAML_WRITE_OPTIONS,
    ...(flow ? { collectionStyle: "flow" } : {}),
    ...(flow || fragment ? { aliasDuplicateObjects: false } : {}),
