      if (error.code !== "EEXIST") throw error;
      if (Date.now() >= deadline)
        throw Object.assign(new ConfigError(
          `Другая операция удерживает блокировку. ${barrier_recovery_hint(lock)}`,
        ), { code: "RUNTIME_BUSY" });
